// ─────────────────────────────────────────────────────────────────────────────
// Validate & Normalize Web Playground Payload
// Accepts POST from Next.js /api/playground/chat and validates required fields.
// Returns normalized context for downstream nodes.
// ─────────────────────────────────────────────────────────────────────────────

const body = $json.body || $json;

const chatbotId   = (body.chatbotId || '').trim();
const sessionId   = (body.sessionId || '').trim();
const userMessage = (body.userMessage || '').trim();
const platform    = (body.platform || 'PLAYGROUND').toUpperCase();
const channel     = (body.channel || body.platform || 'playground').toLowerCase();
const mediaType   = (body.mediaType || 'text').toLowerCase(); // 'text' | 'image' | 'audio'
const mediaUrl    = (body.mediaUrl || '').trim();

// ── Validation ───────────────────────────────────────────────────────────────
if (!chatbotId) {
  throw new Error('Missing required field: chatbotId');
}
if (!sessionId) {
  throw new Error('Missing required field: sessionId');
}
if (!userMessage && mediaType === 'text') {
  throw new Error('Missing required field: userMessage (for text mediaType)');
}
if (mediaType !== 'text' && !mediaUrl) {
  throw new Error(`Missing required field: mediaUrl (required for mediaType '${mediaType}')`);
}

// ── Normalize session prefix ─────────────────────────────────────────────────
const normalizedSessionId = sessionId.startsWith('web_')
  ? sessionId
  : 'web_' + sessionId;

return [{
  json: {
    chatbotId,
    sessionId: normalizedSessionId,
    userMessage,
    platform,
    channel,
    mediaType,
    mediaUrl: mediaUrl || null
  }
}];

// ─────────────────────────────────────────────────────────────────────────────
// Build Brain Payload
// Constructs full payload object for Execute Core AI Brain.
// Ensures $json contains chatbotId, sessionId, userMessage, channel, etc.
// ─────────────────────────────────────────────────────────────────────────────

const payload = $('Validate & Normalize Payload').item.json;

return [{
  json: {
    chatbotId:    payload.chatbotId,
    sessionId:    payload.sessionId,
    customerName: 'Web User',
    profilePhoto: null,
    userMessage:  payload.userMessage || '',
    mediaType:    payload.mediaType || 'text',
    mediaUrl:     payload.mediaUrl || null,
    platform:     payload.platform || 'WEB',
    channel:      payload.channel || 'web'
  }
}];

// ─────────────────────────────────────────────────────────────────────────────
// Build Web Response
// Assembles the structured JSON response to return to the Next.js API route.
// Response shape: { replyText, galleryImages, isOrderCreated, promptTokens, completionTokens, totalTokens, costUsd, costBdt, session }
// Includes null-safety for when Core-AI-Brain errors (continueOnFail=true).
// ─────────────────────────────────────────────────────────────────────────────

let brainOutput = {};
try {
  brainOutput = $('Execute Core AI Brain').item.json || {};
} catch (e) {
  brainOutput = {};
}

const sessionData = $('Upsert Chat Session').item.json || {};
const normPayload = $('Validate & Normalize Payload').item.json || {};

// If Core-AI-Brain errored, brainOutput may have an 'error' key — use fallback
const hadError = !!brainOutput.error;
const replyText = (!hadError && brainOutput.replyText) || '';
const galleryImages = (!hadError && brainOutput.galleryImages) || [];
const isOrderCreated = (!hadError && brainOutput.isOrderCreated) || false;
const promptTokens = (!hadError && brainOutput.promptTokens) || 0;
const completionTokens = (!hadError && brainOutput.completionTokens) || 0;
const totalTokens = (!hadError && brainOutput.totalTokens) || 0;
const costUsd = (!hadError && brainOutput.costUsd) || 0;
const costBdt = (!hadError && brainOutput.costBdt) || 0;

// Pull session info from the Upsert Chat Session RETURNING clause
const session = {
  sessionId: sessionData.sessionId || normPayload.sessionId,
  platform: 'WEB',
  guestName: sessionData.guestName || 'Web User',
  updatedAt: sessionData.updatedAt || new Date().toISOString()
};

return [{
  json: {
    replyText,
    galleryImages,
    isOrderCreated,
    promptTokens,
    completionTokens,
    totalTokens,
    costUsd,
    costBdt,
    session
  }
}];
